SourceCode.Declaration:
/// <summary>
/// Logic Block to create attachment of images to records
/// </summary>
class TFMLogicBlockTakeImage extends TFMLogicBlock implements TFMLogicBlockDataCollectionInterface
{

}

Method.Source:
public void new()
{
    super();
    components.addComponent(new TFMLogicComponentDataContext());
    categories.add("@TFM:Image");
}

public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors               ret = TFMRegistrationCollectors::Construct();
    TFMRegistrationCollectorImageCapture    colImg = new TFMRegistrationCollectorImageCapture(20,extendedTypeStr(ImageDataString), "@TFM:Takeimage", "@TFM:Takeimage", "@TFM:Takeimage");

    ret.addCollector(colImg);
    return ret;        
}

/// <summary>
/// Used if online steps are required
/// </summary>
/// <param name = "_request"></param>
/// <returns></returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    TFMLogicComponentDataContext    dataContext     = components.getComponent(classStr(TFMLogicComponentDataContext));
    Common                          dataToAttachTo  = dataContext.getData(request ? request : new TFMRequestBasicElement());

    //TODO: If no data is in variable, but there are tables in the context object, prompt the user for which table to attach to

    return null;
}

public TFMPostResponseData post()
{
    TFMPostResponseData             postElement     = TFMPostResponseData::Construct();        
    TFMLogicComponentDataContext    dataContext     = components.getComponent(classStr(TFMLogicComponentDataContext));
    Common                          dataToAttachTo  = dataContext.getData(request);
    str                             mediaIDs        = request.getFieldValue(extendedTypeStr(ImageDataString));

    if (mediaIDs && dataToAttachTo)
    {
        TFMMediaQueue::AddMap2Queue(dataToAttachTo, TFMMediaQueue::separateIDsAndComments(mediaIDs), request.parmdeviceID());
    }
    postElement.parmResponseText(strFmt("@TFM:ImageAttachedto", TFMHelper::descriptionFromCommon(dataToAttachTo)));

    return postElement;
}
